package co.serviasigna.domain;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Constancia de que un usuario aceptó una versión de la política (tabla ACEPTACION_POLITICA, RF-M1-06).
 * <p>
 * EN: Record that a user accepted a version of the policy (ACEPTACION_POLITICA table, RF-M1-06).
 */
@Entity
@Table(name = "ACEPTACION_POLITICA")
public class PolicyAcceptance {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El id del usuario. EN: The user id. */
    @Column(name = "USUARIO_ID", nullable = false) private Long userId;
    /** El id de la política. EN: The policy id. */
    @Column(name = "POLITICA_ID", nullable = false) private Long policyId;
    /** La versión aceptada. EN: The accepted version. */
    @Column(name = "VERSION", nullable = false, length = 10) private String version;
    /** La fecha de aceptación. EN: The acceptance date. */
    @Column(name = "FECHA", nullable = false) private LocalDateTime date = LocalDateTime.now();
    /** La dirección IP desde la que aceptó. EN: The IP address it was accepted from. */
    @Column(name = "IP", length = 45) private String ip;

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected PolicyAcceptance() {}

    /**
     * Registra la aceptación con la fecha actual.
     * <p>
     * EN: Records the acceptance with the current date.
     *
     * @param userId id del usuario / user id
     * @param policyId id de la política / policy id
     * @param version versión aceptada / accepted version
     * @param ip dirección IP desde la que aceptó / IP address it was accepted from
     */
    public PolicyAcceptance(long userId, long policyId, String version, String ip) {
        this.userId = userId; this.policyId = policyId; this.version = version; this.ip = ip;
    }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el id del usuario.
     * <p>
     * EN: Returns the user id.
     *
     * @return el id del usuario / the user id
     */
    public Long getUserId() { return userId; }

    /**
     * Devuelve el id de la política.
     * <p>
     * EN: Returns the policy id.
     *
     * @return el id de la política / the policy id
     */
    public Long getPolicyId() { return policyId; }

    /**
     * Devuelve la versión aceptada.
     * <p>
     * EN: Returns the accepted version.
     *
     * @return la versión aceptada / the accepted version
     */
    public String getVersion() { return version; }

    /**
     * Devuelve la fecha de aceptación.
     * <p>
     * EN: Returns the acceptance date.
     *
     * @return la fecha de aceptación / the acceptance date
     */
    public LocalDateTime getDate() { return date; }

    /**
     * Devuelve la dirección IP desde la que aceptó.
     * <p>
     * EN: Returns the IP address it was accepted from.
     *
     * @return la dirección IP desde la que aceptó / the IP address it was accepted from
     */
    public String getIp() { return ip; }
}
